package org.ouyalibre.tv;
import android.app.Instrumentation;import android.os.Bundle;import android.content.Context;import android.net.Uri;import java.io.*;import java.net.*;import java.util.*;
public class IptvDeviceTest extends Instrumentation {
 private int passed=0;private Bundle args;
 public void onCreate(Bundle b){super.onCreate(b);args=b;start();}
 private void check(boolean value,String text){if(!value)throw new AssertionError(text);passed++;Bundle b=new Bundle();b.putString("stream","PASS "+text+"\n");sendStatus(0,b);}
 public void onStart(){Bundle result=new Bundle();IptvStore store=null;List<IptvStore.Entry> created=new ArrayList<IptvStore.Entry>();ServerSocket server=null;try{
  Context c=getTargetContext();store=new IptvStore(c);final ServerSocket socket=new ServerSocket(0,8,InetAddress.getByName("127.0.0.1"));server=socket;final boolean[] fail={false};
  Thread http=new Thread(new Runnable(){public void run(){while(!socket.isClosed())try{Socket peer=socket.accept();try{BufferedReader in=new BufferedReader(new InputStreamReader(peer.getInputStream(),"US-ASCII"));String request=in.readLine(),line;while((line=in.readLine())!=null&&line.length()>0){}String path=request.split(" ")[1];int code=200;String extra="",body="#EXTM3U\n#EXTINF:-1 group-title=\"Noticias\",Canal de prueba unitaria\nchannel.m3u8\n";if(fail[0]){code=500;body="failure";}else if(path.equals("/redirect")){code=302;extra="Location: /nested/list.m3u\r\n";body="";}byte[] bytes=body.getBytes("UTF-8");OutputStream out=peer.getOutputStream();out.write(("HTTP/1.1 "+code+" Test\r\n"+extra+"Content-Length: "+bytes.length+"\r\nConnection: close\r\n\r\n").getBytes("US-ASCII"));out.write(bytes);out.flush();}finally{peer.close();}}catch(Exception ignored){}}});http.setDaemon(true);http.start();
  String address="http://127.0.0.1:"+socket.getLocalPort();IptvStore.Entry a=store.add("__prueba_iptv_A",address+"/redirect");created.add(a);IptvCatalog ca=store.refresh(a,null);check(ca.channels.size()==1,"Real HTTP import into private cache");check(ca.channels.get(0).url.equals(address+"/nested/channel.m3u8"),"Relative channels use final redirect base");
  IptvStore fresh=new IptvStore(c);IptvStore.Entry persisted=null;for(IptvStore.Entry e:fresh.entries())if(e.id.equals(a.id))persisted=e;check(persisted!=null&&fresh.cachedCatalog(persisted).channels.get(0).url.equals(ca.channels.get(0).url),"Redirect base and catalog survive reopening storage");
  File file=new File(c.getCacheDir(),"iptv-unit-fixture.m3u");FileOutputStream out=new FileOutputStream(file);out.write("#EXTM3U\n#EXTINF:-1 group-title=\"Cine\",Otro canal de prueba unitaria\nhttps://example.org/two.m3u8\n".getBytes("UTF-8"));out.close();IptvStore.Entry b=store.add("__prueba_iptv_B",Uri.fromFile(file).toString());created.add(b);IptvCatalog cb=store.refresh(b,null);check(cb.channels.size()==1&&!cb.channels.get(0).title.equals(ca.channels.get(0).title),"File import is separate from the URL playlist");
  store.toggle(a,ca.channels.get(0));check(store.favorites(a).size()==1&&store.favorites(b).isEmpty(),"Favorites are isolated by playlist");store.setHidden(a,ca.channels.get(0).key(),true);check(store.hidden(a).size()==1&&store.hidden(b).isEmpty(),"Hidden marks remain local to their playlist");check(store.cachedCatalog(a).channels.size()==1,"Hiding does not modify cached M3U content");store.setHidden(a,ca.channels.get(0).key(),false);check(store.hidden(a).isEmpty(),"Hidden channel can be restored");store.rename(a,"__prueba_renombrada");check(store.cached(a)&&store.favorites(a).size()==1,"Rename preserves cached channels and favorites");
  fail[0]=true;boolean rejected=false;try{store.refresh(a,null);}catch(Exception expected){rejected=true;}check(rejected&&store.cachedCatalog(a).channels.get(0).url.equals(ca.channels.get(0).url),"Failed HTTP refresh preserves last valid list");
  out=new FileOutputStream(file);out.write("<html>not a playlist</html>".getBytes("UTF-8"));out.close();rejected=false;try{store.refresh(b,null);}catch(Exception expected){rejected=true;}check(rejected&&store.cachedCatalog(b).channels.size()==1,"Invalid replacement file preserves last valid list");
  store.remove(a);created.remove(a);check(!store.cached(a)&&store.cached(b)&&store.favorites(a).isEmpty(),"Delete affects only selected playlist");file.delete();
  for(IptvStore.Entry e:created)store.remove(e);created.clear();
  if(args!=null&&"true".equals(args.getString("importDownloads"))){File downloads=new File("/sdcard/Download");File[] all=downloads.listFiles();check(all!=null,"Read actual Download directory");int imported=0,total=0;List<String> report=new ArrayList<String>();if(all!=null){Arrays.sort(all);for(File f:all){String name=f.getName().toLowerCase(Locale.US);if(!name.endsWith(".m3u")&&!name.endsWith(".m3u8"))continue;String origin=Uri.fromFile(f).toString();IptvStore.Entry entry=null;for(IptvStore.Entry e:store.entries())if(e.origin.equals(origin))entry=e;if(entry==null)entry=store.add(f.getName().replaceFirst("(?i)\\.m3u8?$",""),origin);IptvCatalog cat=store.refresh(entry,null);imported++;total+=cat.channels.size();report.add(entry.name+": "+cat.channels.size()+" canales, "+cat.groups().size()+" grupos");}}check(imported>0,"Import actual user M3U files without merging");result.putString("imported",Integer.toString(imported));result.putString("channels",Integer.toString(total));result.putString("lists",report.toString());}
  result.putString("stream","TOTAL "+passed+" checks passed\n");finish(-1,result);
 }catch(Throwable e){if(store!=null)for(IptvStore.Entry entry:created)try{store.remove(entry);}catch(Exception ignored){}created.clear();result.putString("stream","FAILED: "+e.toString()+"\n");finish(0,result);}finally{if(server!=null)try{server.close();}catch(Exception ignored){}if(store!=null)for(IptvStore.Entry e:created)try{store.remove(e);}catch(Exception ignored){}}}
}
